namespace Aster {
class HelpTopic {
 public string Title,Tags,Body,Page;
 public override string ToString(){return Title;}
 public static HelpTopic[] All={
 new HelpTopic{Title="My PC feels slow",Tags="slow lag cpu memory performance",Page="Processes",Body="Start with a measurement\r\n\r\n1. Open Processes and sort CPU or Memory.\r\n2. Observe while the slowdown happens.\r\n3. Save work before closing an app you recognize.\r\n4. Capture a baseline in Insights, make one change, then compare.\r\n\r\nHigh usage is not automatically a fault. Aster does not identify the root cause from utilization alone."},
 new HelpTopic{Title="An update or Windows feature fails",Tags="update repair dism sfc corruption",Page="Windows advisor",Body="Collect the error first\r\n\r\nRecord the exact error and the operation that failed. Search Error-code help in Windows advisor. Start with read-only diagnosis. A reviewed repair plan is available when the evidence supports it.\r\n\r\nPlans request administrator access and may take time. They stop on failure or a restart-required result. Aster never restarts Windows automatically."},
 new HelpTopic{Title="Get started with local AI",Tags="ai ollama model setup assistant",Page="Windows advisor",Body="Your optional AI counselor\r\n\r\nInstall Ollama and download a local model, then leave its service running. Open Windows advisor → AI counselor → Find local models. Select a model, review your question and click Ask.\r\n\r\nNo model is bundled. Offline guidance uses programmed rules. Including a diagnostic report is optional. Model answers cannot execute commands."},
 new HelpTopic{Title="Prepare a useful support request",Tags="support share report specs export",Page="Hardware report",Body="Give support useful evidence\r\n\r\nWrite the symptom, exact error, timing, reproduction steps and recent changes. Generate a hardware report, review it, then copy or save it. Hardware identifiers are excluded by the report filter.\r\n\r\nYou can also use the support-handoff template in the AI prompt studio. Nothing is sent to another person by Aster."},
 new HelpTopic{Title="Keep monitoring lightweight",Tags="battery eco efficiency overhead",Page="Preferences",Body="Choose a comfortable update rate\r\n\r\nPreferences offers one-, two-, three- and five-second sampling. Longer intervals reduce monitoring work. History charts retain 60 samples, so their time span depends on the interval.\r\n\r\nAura Eco lowers wallpaper animation settings; you can restore its prior profile. These controls tune Aster and Aura, not Windows security or services."},
 new HelpTopic{Title="Some sensor values are unavailable",Tags="gpu temperature sensors missing unavailable",Page="GPU",Body="Unavailable is an honest result\r\n\r\nWindows providers, permissions and vendor support determine which readings exist. Supported NVIDIA devices can provide temperature, clocks and power. Aster does not estimate missing CPU temperatures or fabricate sensor readings.\r\n\r\nTry refreshing the relevant hardware page. A blank reading does not by itself mean the hardware has failed."},
 new HelpTopic{Title="Compare a change fairly",Tags="baseline before after optimization compare",Page="Insights",Body="Change one thing at a time\r\n\r\nUse the same workload, capture a baseline, make one reversible change, and compare again. CPU and memory readings naturally fluctuate. Repeat your original task to see whether the symptom actually improved.\r\n\r\nInsights can prepare its readings for the AI counselor, but you still choose whether to send them."},
 new HelpTopic{Title="Set up live wallpapers",Tags="aura wallpaper video screen battery",Page="Wallpaper studio",Body="Preview before applying\r\n\r\nOpen Aura from Wallpaper studio. Choose a built-in scene or import a local image/video. Configure FPS, battery/fullscreen pause and sound before applying.\r\n\r\nDesktop attachment depends on Windows Explorer compatibility. If unavailable, Aura reports the limitation. Video playback depends on installed Windows codecs."},
 new HelpTopic{Title="Find your saved work",Tags="cases notes logs history saved",Page="Windows advisor",Body="Local records\r\n\r\nSaved cases stores your symptom, displayed report, last AI question/answer and notes only when you click Save. Restore marks the report as historical. Run a fresh scan for current readings.\r\n\r\nRecovery logs and existing cases remain in the legacy Pulse data folder for compatibility with earlier releases. They are plain local files, not cloud backups."},
 new HelpTopic{Title="Make the workspace less distracting",Tags="focus clean shortcuts pins navigation",Page="Focus",Body="Keep the essentials\r\n\r\nFocus shows CPU, memory, process count and uptime, plus recent sampled ranges. Toggle distraction-free mode there or press F11 to hide/show the sidebar. Ctrl+K still opens page navigation.\r\n\r\nPin frequent pages with the header star. Search the sidebar to find a page. Preferences saves your accent and monitoring interval."}
 };
 public static HelpTopic[] Search(string query){var words=query.Split(new[]{' '},StringSplitOptions.RemoveEmptyEntries);return All.Where(t=>words.All(w=>(t.Title+" "+t.Tags+" "+t.Body).IndexOf(w,StringComparison.OrdinalIgnoreCase)>=0)).ToArray();}
}
static class HardwareReport {
 public static bool Shareable(string key){string k=key.ToLowerInvariant();return !new[]{"serial","identifier","device id","processor id","mac address","ip address"}.Any(k.Contains);}
 public static string Format(string title,Table data){var b=new StringBuilder();b.AppendLine(title.ToUpperInvariant());foreach(var row in data.Rows){if(row.Length>=3&&Shareable(row[1]))b.AppendLine(row[0]+" · "+row[1]+": "+row[2]);}if(!string.IsNullOrWhiteSpace(data.Note))b.AppendLine("Note: "+data.Note);return b.ToString();}
 public static string Collect(){var b=new StringBuilder("ASTER · HARDWARE REPORT\r\nGenerated "+DateTime.Now.ToString("g")+"\r\n\r\nHardware inventory, not a health certificate. Serial/device identifiers are excluded. Review before sharing.\r\n\r\n");foreach(var page in new[]{"CPU specs","GPU","Memory specs","Storage specs","Motherboard & BIOS"}){b.AppendLine(Format(page,Inventory.Hardware(page)));b.AppendLine();}return b.ToString();}
}
partial class MainWindow {
 bool distractionFree;MetricTile focusCpu,focusRam,focusProcesses,focusUptime;Label focusReadings;
 TextBox ReadableText(){return new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BorderStyle=BorderStyle.None,BackColor=panel,ForeColor=Color.FromArgb(211,224,240),Font=new Font("Segoe UI",11)};}
 void CleanToolbar(){if(tools==null)return;bool live=new[]{"Summary","Focus","Insights","Performance","Processes","App history","Flight recorder"}.Contains(page);foreach(Button b in tools.Controls.OfType<Button>()){if(b==pause)b.Visible=live;else if(b.Text=="Run new task")b.Visible=page=="Processes";else if(b.Text=="Export CSV")b.Visible=grid!=null||page=="Performance"||page=="Summary"||page=="Flight recorder";else if(b.Text=="Refresh")b.Visible=live||IsInventory();}bool show=live||IsInventory();tools.Visible=show&&!distractionFree;var frame=tools.Parent as TableLayoutPanel;if(frame!=null)frame.RowStyles[1].Height=tools.Visible?47:0;}
 void ToggleFocusMode(){distractionFree=!distractionFree;sidebar.Visible=!distractionFree;CleanToolbar();}
 void BuildFocus(){sub.Text="Essential readings · F11 hides or restores navigation · Ctrl+K jumps to any page";var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=4,Padding=new Padding(0,10,0,0)};root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));root.RowStyles.Add(new RowStyle(SizeType.Absolute,52));root.RowStyles.Add(new RowStyle(SizeType.Absolute,150));root.RowStyles.Add(new RowStyle(SizeType.Absolute,150));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));content.Controls.Add(root);var toggle=Button("Toggle distraction-free view  ·  F11");toggle.Click+=(s,e)=>ToggleFocusMode();root.Controls.Add(toggle,0,0);root.SetColumnSpan(toggle,2);focusCpu=new MetricTile{Caption="PROCESSOR",Accent=cyan};focusRam=new MetricTile{Caption="MEMORY",Accent=Color.FromArgb(178,145,255)};focusProcesses=new MetricTile{Caption="PROCESSES",Accent=Color.FromArgb(95,220,179)};focusUptime=new MetricTile{Caption="WINDOWS UPTIME",Accent=Color.FromArgb(239,184,111)};root.Controls.Add(focusCpu,0,1);root.Controls.Add(focusRam,1,1);root.Controls.Add(focusProcesses,0,2);root.Controls.Add(focusUptime,1,2);focusReadings=Block("Waiting for measurements…",12);root.Controls.Add(focusReadings,0,3);root.SetColumnSpan(focusReadings,2);UpdateFocus();}
 void UpdateFocus(){if(current==null||focusCpu==null||focusCpu.IsDisposed)return;focusCpu.Value=current.Cpu.ToString("F1")+"%";focusCpu.Detail=Environment.ProcessorCount+" logical processors";focusCpu.Level=current.Cpu/100;focusRam.Value=current.MemoryPercent.ToString("F1")+"%";focusRam.Detail=Inventory.Bytes(current.Available)+" available";focusRam.Level=current.MemoryPercent/100;focusProcesses.Value=current.Processes.Count.ToString();focusProcesses.Detail="Visible in the latest sample";focusProcesses.Level=0;focusUptime.Value=TimeSpan.FromMilliseconds(Native.GetTickCount64()).ToString(@"d\d\ hh\h\ mm\m");focusUptime.Detail="Windows-reported time since boot";focusUptime.Level=0;focusReadings.Text=(paused?"PAUSED":"LIVE")+" · sampled "+current.Time.ToString("T")+"\r\n\r\n"+(history.Count==0?"":history.Count+" recent samples\r\nCPU range "+history.Min(x=>x.Cpu).ToString("F1")+"–"+history.Max(x=>x.Cpu).ToString("F1")+"%\r\nMemory range "+history.Min(x=>x.MemoryPercent).ToString("F1")+"–"+history.Max(x=>x.MemoryPercent).ToString("F1")+"%")+"\r\n\r\nReadings reuse the existing sampler. No additional system monitoring runs for this view.";foreach(var t in new[]{focusCpu,focusRam,focusProcesses,focusUptime})t.Invalidate();}
 void BuildHelpCenter(){sub.Text="Practical, searchable guides · available without an AI model";var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=3};root.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,300));root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,50));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,52));content.Controls.Add(root);var searchHelp=new TextBox{Dock=DockStyle.Top,Font=new Font("Segoe UI",12),Margin=new Padding(0,5,18,10)};root.Controls.Add(searchHelp,0,0);root.Controls.Add(new Label{Text="Search a symptom or feature, such as “slow”, “AI”, or “wallpaper”.",Dock=DockStyle.Fill,ForeColor=muted,Padding=new Padding(12,8,0,0)},1,0);var list=new ListBox{Dock=DockStyle.Fill,BorderStyle=BorderStyle.None,BackColor=panel,ForeColor=Color.White,Font=new Font("Segoe UI",11),ItemHeight=34,Margin=new Padding(0,0,18,10)};list.DrawMode=DrawMode.OwnerDrawFixed;list.DrawItem+=(s,e)=>{if(e.Index<0)return;e.DrawBackground();TextRenderer.DrawText(e.Graphics,list.Items[e.Index].ToString(),list.Font,e.Bounds,Color.White,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);};root.Controls.Add(list,0,1);var detail=ReadableText();detail.Margin=new Padding(18,8,18,12);root.Controls.Add(detail,1,1);var open=Button("Open related tool →");root.Controls.Add(open,1,2);Action refreshHelp=()=>{list.Items.Clear();list.Items.AddRange(HelpTopic.Search(searchHelp.Text));open.Enabled=list.Items.Count>0;if(list.Items.Count>0)list.SelectedIndex=0;else detail.Text="No matching guide. Try a shorter search or open Windows advisor to describe your issue.";};list.SelectedIndexChanged+=(s,e)=>{var item=list.SelectedItem as HelpTopic;if(item!=null)detail.Text=item.Title.ToUpperInvariant()+"\r\n\r\n"+item.Body;};open.Click+=(s,e)=>{var item=list.SelectedItem as HelpTopic;if(item!=null)Navigate(item.Page);};searchHelp.TextChanged+=(s,e)=>refreshHelp();refreshHelp();}
 void BuildHardwareReport(){sub.Text="CPU, graphics, memory, storage and motherboard · review before sharing";var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3};root.RowStyles.Add(new RowStyle(SizeType.Absolute,56));root.RowStyles.Add(new RowStyle(SizeType.Absolute,44));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));content.Controls.Add(root);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill};root.Controls.Add(actions,0,0);var generate=Button("Generate hardware report");var copy=Button("Copy report");var save=Button("Save as text");copy.Enabled=save.Enabled=false;actions.Controls.Add(generate);actions.Controls.Add(copy);actions.Controls.Add(save);var state=new Label{Dock=DockStyle.Fill,ForeColor=muted,Text="Only generated when requested. Nothing is uploaded."};root.Controls.Add(state,0,1);var text=ReadableText();text.Text="A useful inventory for support or your own records.\r\n\r\nThe report excludes serial numbers and device/processor identifiers. Provider failures are included as unavailable readings. Review the report before sharing it.\r\n\r\nGenerating may take time while Windows reads hardware information.";root.Controls.Add(text,0,2);generate.Click+=async(s,e)=>{generate.Enabled=false;state.Text="Reading Windows hardware providers…";try{string data=await Task.Run(()=>HardwareReport.Collect());if(text.IsDisposed)return;text.Text=data;copy.Enabled=save.Enabled=true;state.Text="Report ready · review before copying or saving.";}catch(Exception ex){if(!state.IsDisposed)state.Text="Could not generate report: "+ex.Message;}finally{if(!generate.IsDisposed)generate.Enabled=true;}};copy.Click+=(s,e)=>{try{Clipboard.SetText(text.Text);state.Text="Copied. Nothing has been sent to another person.";}catch(Exception ex){state.Text=ex.Message;}};save.Click+=(s,e)=>{using(var d=new SaveFileDialog{Filter="Text report|*.txt",FileName="Aster-hardware-"+DateTime.Now.ToString("yyyyMMdd")+".txt"})if(d.ShowDialog(this)==DialogResult.OK){try{File.WriteAllText(d.FileName,text.Text,Encoding.UTF8);state.Text="Saved report.";}catch(Exception ex){state.Text=ex.Message;}}};}
}
}

